import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  List,
  ListItem,
  ListItemText,
  CircularProgress,
} from '@mui/material';

// Giả lập dữ liệu các tương tác gần đây qua Zalo chatbot
const mockInteractions = [
  { id: 1, name: 'Khách hàng A', message: 'Chào bạn, tôi muốn hỏi về dự án căn hộ Quận 7', time: '10:30 AM - 17/09/2025' },
  { id: 2, name: 'Khách hàng B', message: 'Giá bán của căn 2 phòng ngủ là bao nhiêu?', time: '09:45 AM - 17/09/2025' },
  { id: 3, name: 'Khách hàng C', message: 'Tôi có thể xem nhà mẫu vào cuối tuần được không?', time: '08:15 AM - 17/09/2025' },
];

const CustomerInteractionsPage = () => {
  const [interactions, setInteractions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Gọi API để lấy lịch sử tương tác chatbot
    // const fetchInteractions = async () => {
    //   const response = await fetch('/api/chatbot-interactions');
    //   const result = await response.json();
    //   setInteractions(result);
    //   setLoading(false);
    // };
    // fetchInteractions();

    // Dùng dữ liệu giả lập để demo
    const timer = setTimeout(() => {
      setInteractions(mockInteractions);
      setLoading(false);
    }, 1000);
    return () => clearTimeout(timer);
  }, []);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h4" gutterBottom>
        Tương tác Khách hàng
      </Typography>
      <Typography variant="body1" sx={{ mb: 4 }}>
        Quản lý các tương tác đến từ Zalo chatbot của bạn. [cite: 563]
      </Typography>
      <Paper elevation={3} sx={{ p: 2 }}>
        <List>
          {interactions.length > 0 ? (
            interactions.map((interaction) => (
              <ListItem key={interaction.id} divider>
                <ListItemText
                  primary={
                    <React.Fragment>
                      <Typography component="span" variant="body1" color="text.primary" fontWeight="bold">
                        {interaction.name}
                      </Typography>
                      {' - '}
                      <Typography component="span" variant="body2" color="text.secondary">
                        {interaction.time}
                      </Typography>
                    </React.Fragment>
                  }
                  secondary={interaction.message}
                />
              </ListItem>
            ))
          ) : (
            <Typography variant="body2" color="text.secondary" align="center" sx={{ p: 2 }}>
              Chưa có tương tác nào từ Zalo chatbot.
            </Typography>
          )}
        </List>
      </Paper>
    </Box>
  );
};

export default CustomerInteractionsPage;
